class LineBuffer:
    """Split a byte stream at LF without decoding or changing any other byte."""

    def __init__(self):
        self._pending = bytearray()

    def feed(self, chunk: bytes) -> list[bytes]:
        lines: list[bytes] = []
        for value in chunk:
            if value == 10:
                lines.append(bytes(self._pending))
                self._pending.clear()
            else:
                self._pending.append(value)
